  "input_format"?: "auto" | "xyz" | "mol" | "pdb" | "sdf" | "cif";
  /** Total charge, used for RDKit bond-order perception (rdDetermineBonds.DetermineBonds). Default 0. (default=0) */
  "charge"?: number;
